reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select test.denied($q$select public.admin_save_catalogue_term('brand','50000000-0000-4000-8000-000000000001',null,'{"name":"Unauthorized","slug":"unauthorized","published":true}')$q$,'42501','customer cannot create taxonomy');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select test.denied($q$select public.admin_save_catalogue_term('category','50000000-0000-4000-8000-000000000003',null,'{"name":"Unauthorized","slug":"unauthorized","published":false}')$q$,'42501','taxonomy requires Owner MFA');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select public.admin_save_catalogue_term('brand','50000000-0000-4000-8000-000000000001',null,'{"name":"Synthetic brand","slug":"synthetic-brand","published":true}');
select public.admin_save_catalogue_term('brand','50000000-0000-4000-8000-000000000002',null,'{"name":"Second synthetic brand","slug":"second-synthetic-brand","published":false}');
select public.admin_save_catalogue_term('category','50000000-0000-4000-8000-000000000003',null,'{"name":"Synthetic category","slug":"synthetic-category","published":false}');
select public.admin_save_catalogue_term('collection','50000000-0000-4000-8000-000000000004',null,'{"name":"Synthetic collection","slug":"synthetic-collection","published":false}');
select test.assert_true((select count(*)=3 from public.catalogue_terms where id::text like '50000000%'),'manager creates actual persisted brand and collection records');
set local role anon;
select test.assert_true((select count(*)=0 from public.catalogue_terms),'published brand without offered published products remains hidden publicly');
set local role authenticated;
select public.admin_set_product_taxonomy('10000000-0000-4000-8000-000000000001',(select updated_at from public.products where id='10000000-0000-4000-8000-000000000001'),'50000000-0000-4000-8000-000000000003',array['50000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000004']::uuid[]);
select test.assert_true((select category_id='50000000-0000-4000-8000-000000000003' from public.products where id='10000000-0000-4000-8000-000000000001'),'category assignment persists');
select test.assert_true((select count(*)=2 from public.product_catalogue_terms where product_id='10000000-0000-4000-8000-000000000001'),'brand and collection assignment persist');
select test.denied($q$select public.admin_set_product_taxonomy('10000000-0000-4000-8000-000000000001',(select updated_at from public.products where id='10000000-0000-4000-8000-000000000001'),null,array['50000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000002']::uuid[])$q$,'22023','cannot assign multiple brands to a product');
select test.denied($q$select public.admin_delete_catalogue_term('category','50000000-0000-4000-8000-000000000003',(select updated_at from public.categories where id='50000000-0000-4000-8000-000000000003'))$q$,'23503','assigned category cannot be deleted');
select test.denied($q$select public.admin_delete_catalogue_term('brand','50000000-0000-4000-8000-000000000002',now()-interval '1 day')$q$,'PT409','term deletion rejects stale version');
select public.admin_delete_catalogue_term('brand','50000000-0000-4000-8000-000000000002',(select updated_at from public.catalogue_terms where id='50000000-0000-4000-8000-000000000002'));
select test.assert_true((select count(*)=0 from public.catalogue_terms where id='50000000-0000-4000-8000-000000000002'),'unused unpublished record deletion persists');
select test.assert_true((select count(*)=1 from public.admin_audit_logs where action='catalogue.term_deleted' and target_id='50000000-0000-4000-8000-000000000002'),'taxonomy deletion is audited');
reset role;
